11	// AscendC kernel: MoeGatingTopK
12	// Computes: softmax + topK + finish_mask + source_row_out for each row
13	// Supports: float32 (dtypeFlag=0), float16 (dtypeFlag=1), bfloat16 (dtypeFlag=2)
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 1;
18	constexpr int32_t MAX_K = 128;
19	constexpr int32_t TILE_LEN = 2048;
20	
21	#define U32_MUL(val, sz) static_cast<uint32_t>(static_cast<uint32_t>(val) * static_cast<uint32_t>(sz))
22	
23	__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
24	    if (b == 0U) return 0U;
25	    return (a + b - 1U) / b;
26	}
27	
28	template <typename T>
29	class KernelMoeGatingTopK {
30	public:
31	    __aicore__ inline void Init(
32	        GM_ADDR xGm, GM_ADDR finishedGm, GM_ADDR workspaceGm,
33	        GM_ADDR outGm, GM_ADDR indicesGm, GM_ADDR srcRowOutGm,
34	        int32_t M, int32_t N, int32_t K,
35	        int32_t hasFinished, int32_t tileLen,
36	        int32_t tailTileLen, int32_t usedCoreNum,
37	        int32_t rowsPerCore)
38	    {
39	        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xGm));
40	        finishedGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(finishedGm));
41	        workspaceGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(workspaceGm));
42	        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(outGm));
43	        indicesGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(indicesGm));
44	        srcRowOutGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(srcRowOutGm));
45	        M_ = M; N_ = N; K_ = K; hasFinished_ = hasFinished;
46	        tileLen_ = tileLen; tailTileLen_ = tailTileLen;
47	        usedCoreNum_ = usedCoreNum; rowsPerCore_ = rowsPerCore;
48	
49	        pipe_.InitBuffer(queIn_, BUFFER_NUM, tileLen_ * sizeof(T));
50	        pipe_.InitBuffer(queOut_, BUFFER_NUM, tileLen_ * sizeof(T));
51	        if constexpr (!std::is_same_v<T, float>) {
52	            pipe_.InitBuffer(castFp32Buf_, tileLen_ * sizeof(float));
53	        }
54	        pipe_.InitBuffer(expBuf_, tileLen_ * sizeof(float));
55	        pipe_.InitBuffer(topkValBuf_, MAX_K * sizeof(float));
56	        pipe_.InitBuffer(topkIdxBuf_, MAX_K * sizeof(int32_t));
57	        pipe_.InitBuffer(maxBuf_, sizeof(float));
58	        pipe_.InitBuffer(sumBuf_, sizeof(float));
59	        pipe_.InitBuffer(reduceBuf_, 2 * tileLen_ * sizeof(float));
60	        pipe_.InitBuffer(srcRowBuf_, MAX_K * sizeof(int32_t));
61	    }
62	
63	    __aicore__ inline void Process() {
64	        int32_t cid = static_cast<int32_t>(AscendC::GetBlockIdx());
65	        rowStart_ = cid * rowsPerCore_;
66	        rowEnd_ = rowStart_ + rowsPerCore_;
67	        if (rowEnd_ > M_) rowEnd_ = M_;
68	        for (int32_t row = rowStart_; row < rowEnd_; ++row) ProcessRow(row);
69	    }
70	
71	private:
72	    __aicore__ inline void ProcessRow(int32_t row) {
73	        if (row >= M_) return;
74	        {
75	            auto maxLocal = maxBuf_.Get<float>();
76	            auto sumLocal = sumBuf_.Get<float>();
77	            AscendC::Duplicate<float>(maxLocal, -3.402823466e+38f, 1);
78	            AscendC::Duplicate<float>(sumLocal, 0.0f, 1);
79	        }
80	        int32_t numTiles = static_cast<int32_t>(CeilDiv(static_cast<uint32_t>(N_), static_cast<uint32_t>(tileLen_)));
81	        // Pass 1: Find global max for numerical stability
82	        SoftmaxMaxPass(row, numTiles);
83	        // Pass 2: exp(x-max), accumulate sum, store exp to workspace
84	        SoftmaxExpSumPass(row, numTiles);
85	        // Pass 3: Load exp, normalize in scalar, topK, write softmax to workspace
86	        SoftmaxTopKPass(row, numTiles);
87	        PostProcess(row);
88	    }
89	
90	    __aicore__ inline int32_t CurLenForTile(int32_t ti, int32_t numTiles) {
91	        return (ti == numTiles - 1 && N_ % tileLen_ != 0) ? tailTileLen_ : tileLen_;
92	    }
93	
94	    __aicore__ inline void SoftmaxMaxPass(int32_t row, int32_t numTiles) {
95	        auto maxLocal = maxBuf_.Get<float>();
96	        auto reduceLocal = reduceBuf_.Get<float>();
97	        for (int32_t ti = 0; ti < numTiles; ++ti) {
98	            int32_t col = ti * tileLen_;
99	            int32_t curLen = CurLenForTile(ti, numTiles);
100	            auto inLocal = queIn_.AllocTensor<T>();
101	            AscendC::DataCopyExtParams cp{1, U32_MUL(curLen, sizeof(T)), 0, 0, 0};
102	            AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
103	            AscendC::DataCopyPad(inLocal, xGm_[row * N_ + col], cp, pp);
104	            queIn_.EnQue(inLocal);
105	            auto xIn = queIn_.DeQue<T>();
106	            AscendC::LocalTensor<float> xF32;
107	            if constexpr (std::is_same_v<T, float>) {
108	                xF32 = xIn.template ReinterpretCast<float>();
109	            } else {
110	                xF32 = castFp32Buf_.Get<float>();
111	                AscendC::Cast(xF32, xIn, AscendC::RoundMode::CAST_NONE, curLen);
112	                AscendC::PipeBarrier<PIPE_V>();
113	            }
114	            AscendC::ReduceMax<float>(xF32, xF32, reduceLocal, curLen);
115	            AscendC::PipeBarrier<PIPE_V>();
116	            AscendC::Max(maxLocal, maxLocal, xF32, 1);
117	            AscendC::PipeBarrier<PIPE_V>();
118	            queIn_.FreeTensor(xIn);
119	        }
120	    }
121	
122	    __aicore__ inline void SoftmaxExpSumPass(int32_t row, int32_t numTiles) {
123	        auto maxLocal = maxBuf_.Get<float>();
124	        auto sumLocal = sumBuf_.Get<float>();
125	        auto reduceLocal = reduceBuf_.Get<float>();
126	        float maxVal = maxLocal.GetValue(0);
127	        for (int32_t ti = 0; ti < numTiles; ++ti) {
128	            int32_t col = ti * tileLen_;
129	            int32_t curLen = CurLenForTile(ti, numTiles);
130	            auto inLocal = queIn_.AllocTensor<T>();
131	            AscendC::DataCopyExtParams cp{1, U32_MUL(curLen, sizeof(T)), 0, 0, 0};
132	            AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
133	            AscendC::DataCopyPad(inLocal, xGm_[row * N_ + col], cp, pp);
134	            queIn_.EnQue(inLocal);
135	            auto xIn = queIn_.DeQue<T>();
136	            AscendC::LocalTensor<float> xF32;
137	            if constexpr (std::is_same_v<T, float>) {
138	                xF32 = xIn.template ReinterpretCast<float>();
139	            } else {
140	                xF32 = castFp32Buf_.Get<float>();
141	                AscendC::Cast(xF32, xIn, AscendC::RoundMode::CAST_NONE, curLen);
142	                AscendC::PipeBarrier<PIPE_V>();
143	            }
144	            AscendC::Adds(xF32, xF32, static_cast<float>(-maxVal), curLen);
145	            AscendC::PipeBarrier<PIPE_V>();
146	            auto expLocal = expBuf_.Get<float>();
147	            AscendC::Exp(expLocal, xF32, curLen);
148	            AscendC::PipeBarrier<PIPE_V>();
149	            AscendC::ReduceSum<float>(expLocal, expLocal, reduceLocal, curLen);
150	            AscendC::PipeBarrier<PIPE_V>();
151	            AscendC::Add(sumLocal, sumLocal, expLocal, 1);
152	            AscendC::PipeBarrier<PIPE_V>();
153	            AscendC::Exp(expLocal, xF32, curLen);
154	            AscendC::PipeBarrier<PIPE_V>();
155	            AscendC::DataCopyExtParams cp2{1, U32_MUL(curLen, sizeof(float)), 0, 0, 0};
156	            AscendC::DataCopyPad(workspaceGm_[row * N_ + col], expLocal, cp2);
157	            queIn_.FreeTensor(xIn);
158	        }
159	    }
160	
161	    __aicore__ inline void SoftmaxTopKPass(int32_t row, int32_t numTiles) {
162	        auto sumLocal = sumBuf_.Get<float>();
163	        float sumVal = sumLocal.GetValue(0);
164	        float invSum = (sumVal > 0.0f) ? (1.0f / sumVal) : 1.0f;
165	        {
166	            auto tv = topkValBuf_.Get<float>();
167	            auto ti = topkIdxBuf_.Get<int32_t>();
168	            AscendC::Duplicate<float>(tv, -3.402823466e+38f, MAX_K);
169	            AscendC::Duplicate<int32_t>(ti, 0, MAX_K);
170	        }
171	        for (int32_t ti = 0; ti < numTiles; ++ti) {
172	            int32_t col = ti * tileLen_;
173	            int32_t curLen = CurLenForTile(ti, numTiles);
174	            auto expF32 = expBuf_.Get<float>();
175	            AscendC::DataCopyExtParams cp{1, U32_MUL(curLen, sizeof(float)), 0, 0, 0};
176	            AscendC::DataCopyPadExtParams<float> pp{false, 0, 0, 0.0f};
177	            AscendC::DataCopyPad(expF32, workspaceGm_[row * N_ + col], cp, pp);
178	            AscendC::PipeBarrier<PIPE_MTE2>();
179	            StreamingTopKInline(curLen, col, expF32, invSum);
180	            AscendC::PipeBarrier<PIPE_V>();
181	        }
182	    }
183	
184	    __aicore__ inline void StreamingTopKInline(int32_t curLen, int32_t colBase,
185	                                                AscendC::LocalTensor<float> &vals, float inv) {
186	        auto topV = topkValBuf_.Get<float>();
187	        auto topI = topkIdxBuf_.Get<int32_t>();
188	        for (int32_t i = 0; i < curLen; ++i) {
189	            float raw = vals.GetValue(i);
190	            if (raw <= -3.0e38f) continue;
191	            float v = raw * inv;
192	            int32_t idx = colBase + i;
193	            int32_t pos = -1;
194	            for (int32_t p = 0; p < K_; ++p) {
195	                if (v > topV.GetValue(p)) { pos = p; break; }
196	            }
197	            if (pos >= 0 && pos < K_) {
198	                for (int32_t p = K_ - 1; p > pos; --p) {
199	                    topV.SetValue(p, topV.GetValue(p - 1));
200	                    topI.SetValue(p, topI.GetValue(p - 1));
201	                }
202	                topV.SetValue(pos, v);
203	                topI.SetValue(pos, idx);
204	            }
205	        }
206	    }
207	
208	    __aicore__ inline void PostProcess(int32_t row) {
209	        auto topV = topkValBuf_.Get<float>();
210	        auto topI = topkIdxBuf_.Get<int32_t>();
211	
212	        if (hasFinished_ == 1 && finishedGm_.GetValue(row) != 0) {
213	            AscendC::Duplicate<int32_t>(topI, N_, K_);
214	        }
215	
216	        if constexpr (std::is_same_v<T, float>) {
217	            AscendC::DataCopyExtParams cp{1, U32_MUL(K_, sizeof(float)), 0, 0, 0};
218	            AscendC::DataCopyPad(outGm_[row * K_], topV, cp);
219	        } else {
220	            auto outVal = queOut_.AllocTensor<T>();
221	            AscendC::RoundMode rm = std::is_same_v<T, bfloat16_t> ?
222	                AscendC::RoundMode::CAST_ROUND : AscendC::RoundMode::CAST_NONE;
223	            AscendC::Cast(outVal, topV, rm, K_);
224	            AscendC::PipeBarrier<PIPE_V>();
225	            AscendC::DataCopyExtParams cp2{1, U32_MUL(K_, sizeof(T)), 0, 0, 0};
226	            AscendC::DataCopyPad(outGm_[row * K_], outVal, cp2);
227	            queOut_.FreeTensor(outVal);
228	        }
229	
230	        AscendC::DataCopyExtParams cp{1, U32_MUL(K_, sizeof(int32_t)), 0, 0, 0};
231	        AscendC::DataCopyPad(indicesGm_[row * K_], topI, cp);
232	
233	        auto srcRow = srcRowBuf_.Get<int32_t>();
234	        for (int32_t j = 0; j < K_; ++j) {
235	            srcRow.SetValue(j, j * M_ + row);
236	        }
237	        AscendC::PipeBarrier<PIPE_V>();
238	        AscendC::DataCopyExtParams cp2{1, U32_MUL(K_, sizeof(int32_t)), 0, 0, 0};
239	        AscendC::DataCopyPad(srcRowOutGm_[row * K_], srcRow, cp2);
240	    }
241	
242	    AscendC::TPipe pipe_;
243	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> queIn_;
244	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> queOut_;
245	    AscendC::TBuf<AscendC::TPosition::VECCALC> castFp32Buf_, expBuf_, topkValBuf_;
246	    AscendC::TBuf<AscendC::TPosition::VECCALC> topkIdxBuf_, maxBuf_, sumBuf_;
247	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_, srcRowBuf_;
248	    AscendC::GlobalTensor<T> xGm_;
249	    AscendC::GlobalTensor<int32_t> finishedGm_;
250	    AscendC::GlobalTensor<float> workspaceGm_;
251	    AscendC::GlobalTensor<T> outGm_;
252	    AscendC::GlobalTensor<int32_t> indicesGm_;
253	    AscendC::GlobalTensor<int32_t> srcRowOutGm_;
254	    int32_t M_, N_, K_, hasFinished_, tileLen_, tailTileLen_;
255	    int32_t usedCoreNum_, rowsPerCore_, rowStart_, rowEnd_;
256	};
257	
258	extern "C" __global__ __aicore__ void moe_gating_topk(
259	    GM_ADDR x, GM_ADDR finished, GM_ADDR workspace,
260	    GM_ADDR out, GM_ADDR indices, GM_ADDR srcRowOut,
261	    int32_t M, int32_t N, int32_t K,
262	    int32_t hasFinished, int32_t tileLen,
263	    int32_t tailTileLen, int32_t usedCoreNum,
264	    int32_t rowsPerCore, int64_t dtypeFlag)
265	{
266	    if (dtypeFlag == 0) {
267	        KernelMoeGatingTopK<float> kern;
268	        kern.Init(x, finished, workspace, out, indices, srcRowOut, M, N, K,
269	                  hasFinished, tileLen, tailTileLen, usedCoreNum, rowsPerCore);
270	        kern.Process();
271	    } else if (dtypeFlag == 1) {
272	        KernelMoeGatingTopK<half> kern;
273	        kern.Init(x, finished, workspace, out, indices, srcRowOut, M, N, K,
274	                  hasFinished, tileLen, tailTileLen, usedCoreNum, rowsPerCore);
275	        kern.Process();
276	    } else {
277	        KernelMoeGatingTopK<bfloat16_t> kern;
278	        kern.Init(x, finished, workspace, out, indices, srcRowOut, M, N, K,
279	                  hasFinished, tileLen, tailTileLen, usedCoreNum, rowsPerCore);
280	        kern.Process();
281	    }
282	}
