11	// MoeGatingTopK op_host — tiling calculation + EXEC_KERNEL_CMD launch
12	// Supports float32 (dtypeFlag=0), float16 (dtypeFlag=1), bfloat16 (dtypeFlag=2)
13	
14	#include <algorithm>
15	#include <cstdint>
16	#include <vector>
17	
18	#include <torch/extension.h>
19	#include <torch/library.h>
20	
21	#include "torch_kernel_helper.h"
22	#include "tiling/platform/platform_ascendc.h"
23	
24	#include "aclrtlaunch_moe_gating_topk.h"
25	
26	namespace ascend_kernel {
27	
28	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
29	constexpr int32_t DEFAULT_TILE_LEN = 2048;
30	
31	std::vector<at::Tensor> moe_gating_topk(
32	    const at::Tensor &x,
33	    const c10::optional<at::Tensor> &finishedOptional,
34	    int64_t k)
35	{
36	    // Input validation
37	    TORCH_CHECK(x.dim() == 2, "x must be [batch, num_experts]");
38	    TORCH_CHECK(
39	        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
40	            x.scalar_type() == at::kBFloat16,
41	        "x must be float32, float16, or bfloat16");
42	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
43	    TORCH_CHECK(k > 0, "k must be positive");
44	
45	    int32_t M = static_cast<int32_t>(x.sizes()[0]);
46	    int32_t N = static_cast<int32_t>(x.sizes()[1]);
47	    int32_t K = static_cast<int32_t>(k);
48	
49	    // finished_optional: convert bool to int32 for kernel
50	    int32_t hasFinished = 0;
51	    at::Tensor finishedTensor;
52	    if (finishedOptional.has_value()) {
53	        hasFinished = 1;
54	        finishedTensor = finishedOptional.value();
55	        TORCH_CHECK(finishedTensor.dim() == 1, "finished_optional must be 1D");
56	        TORCH_CHECK(static_cast<int32_t>(finishedTensor.sizes()[0]) == M,
57	                    "finished_optional batch size mismatch");
58	        TORCH_CHECK(finishedTensor.scalar_type() == at::kBool,
59	                    "finished_optional must be bool");
60	        finishedTensor = finishedTensor.to(at::kInt);
61	    } else {
62	        finishedTensor = at::zeros({M}, at::TensorOptions().dtype(at::kInt).device(x.device()));
63	    }
64	
65	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
66	    int64_t dtypeFlag = 0;
67	    if (x.scalar_type() == at::kHalf) {
68	        dtypeFlag = 1;
69	    } else if (x.scalar_type() == at::kBFloat16) {
70	        dtypeFlag = 2;
71	    }
72	
73	    // Output allocation
74	    auto optionsVal = x.options();
75	    auto optionsIdx = at::TensorOptions().dtype(at::kInt).device(x.device());
76	    at::Tensor out = at::empty({M, K}, optionsVal);
77	    at::Tensor indices = at::empty({M, K}, optionsIdx);
78	    at::Tensor sourceRowOut = at::empty({M, K}, optionsIdx);
79	
80	    // Internal workspace (float32, stored in GM) for softmax intermediate
81	    at::Tensor workspace = at::empty({M, N}, optionsVal.dtype(at::kFloat));
82	
83	    // Tiling calculation
84	    int32_t usedCoreNum = std::min(DEFAULT_NUM_PHYSICAL_CORES, std::max(1, M));
85	    int32_t rowsPerCore = (M + usedCoreNum - 1) / usedCoreNum;
86	
87	    int32_t tileLen = std::min(DEFAULT_TILE_LEN, N);
88	    if (tileLen % 32 != 0) {
89	        tileLen = ((tileLen / 32) + 1) * 32;
90	    }
91	    int32_t tailTileLen = N % tileLen;
92	    if (tailTileLen == 0) {
93	        tailTileLen = tileLen;
94	    }
95	
96	    // EXEC_KERNEL_CMD requires all params as left values
97	    int32_t mVal = M;
98	    int32_t nVal = N;
99	    int32_t kVal = K;
100	    int32_t hasFinishedVal = hasFinished;
101	    int32_t tileLenVal = tileLen;
102	    int32_t tailTileLenVal = tailTileLen;
103	    int32_t usedCoreNumVal = usedCoreNum;
104	    int32_t rowsPerCoreVal = rowsPerCore;
105	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
106	
107	    EXEC_KERNEL_CMD(moe_gating_topk, blockDim,
108	                    x, finishedTensor, workspace, out, indices, sourceRowOut,
109	                    mVal, nVal, kVal, hasFinishedVal,
110	                    tileLenVal, tailTileLenVal, usedCoreNumVal, rowsPerCoreVal,
111	                    dtypeFlag);
112	
113	    return {out, indices, sourceRowOut};
114	}
115	
116	}  // namespace ascend_kernel
