// AscendC kernel: MoeGatingTopKSoftmax
// Computes: softmax + topK + finish_mask + source_row_out for each row
// Multi-pass algorithm:
//   Pass 1: Max reduction across tiles for numerical stability
//   Pass 2: exp(x-max) + sum accumulation, store exp in GM workspace
//   Pass 3: Softmax normalization + streaming top-k per tile + merge
//   Pass 4: Post-processing (finish mask + source_row_out + write outputs)
// Supports: float32 (dtypeFlag=0), float16 (dtypeFlag=1), bfloat16 (dtypeFlag=2)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t MAX_K = 128;
constexpr int32_t TILE_LEN = 2048;

#define U32_MUL(val, sz) static_cast<uint32_t>(static_cast<uint32_t>(val) * static_cast<uint32_t>(sz))

__aicore__ inline uint32_t CeilDiv(uint32_t a, uint32_t b) {
    if (b == 0U) return 0U;
    return (a + b - 1U) / b;
}

template <typename T>
class KernelMoeGatingTopKSoftmax {
public:
    __aicore__ inline void Init(
        GM_ADDR xGm, GM_ADDR finishedGm, GM_ADDR workspaceGm,
        GM_ADDR outGm, GM_ADDR indicesGm, GM_ADDR srcRowOutGm,
        int32_t M, int32_t N, int32_t K,
        int32_t hasFinished, int32_t tileLen,
        int32_t tailTileLen, int32_t usedCoreNum,
        int32_t rowsPerCore)
    {
        xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(xGm));
        finishedGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(finishedGm));
        workspaceGm_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(workspaceGm));
        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(outGm));
        indicesGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(indicesGm));
        srcRowOutGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(srcRowOutGm));
        M_ = M; N_ = N; K_ = K; hasFinished_ = hasFinished;
        tileLen_ = tileLen; tailTileLen_ = tailTileLen;
        usedCoreNum_ = usedCoreNum; rowsPerCore_ = rowsPerCore;

        pipe_.InitBuffer(queIn_, BUFFER_NUM, tileLen_ * sizeof(T));
        pipe_.InitBuffer(queOut_, BUFFER_NUM, tileLen_ * sizeof(T));
        if constexpr (!std::is_same_v<T, float>) {
            pipe_.InitBuffer(castFp32Buf_, tileLen_ * sizeof(float));
        }
        pipe_.InitBuffer(expBuf_, tileLen_ * sizeof(float));
        pipe_.InitBuffer(topkValBuf_, MAX_K * sizeof(float));
        pipe_.InitBuffer(topkIdxBuf_, MAX_K * sizeof(int32_t));
        pipe_.InitBuffer(maxBuf_, sizeof(float));
        pipe_.InitBuffer(sumBuf_, sizeof(float));
        pipe_.InitBuffer(reduceBuf_, 2 * tileLen_ * sizeof(float));
        pipe_.InitBuffer(srcRowBuf_, MAX_K * sizeof(int32_t));
    }

    __aicore__ inline void Process() {
        int32_t cid = static_cast<int32_t>(AscendC::GetBlockIdx());
        rowStart_ = cid * rowsPerCore_;
        rowEnd_ = rowStart_ + rowsPerCore_;
        if (rowEnd_ > M_) rowEnd_ = M_;
        for (int32_t row = rowStart_; row < rowEnd_; ++row) ProcessRow(row);
    }

private:
    __aicore__ inline void ProcessRow(int32_t row) {
        if (row >= M_) return;
        {
            auto maxLocal = maxBuf_.Get<float>();
            auto sumLocal = sumBuf_.Get<float>();
            AscendC::Duplicate<float>(maxLocal, -3.402823466e+38f, 1);
            AscendC::Duplicate<float>(sumLocal, 0.0f, 1);
        }
        int32_t numTiles = static_cast<int32_t>(CeilDiv(static_cast<uint32_t>(N_), static_cast<uint32_t>(tileLen_)));
        // Pass 1: Find global max for numerical stability
        SoftmaxMaxPass(row, numTiles);
        // Pass 2: exp(x-max), accumulate sum, store exp to workspace
        SoftmaxExpSumPass(row, numTiles);
        // Pass 3: Load exp from workspace, normalize, streaming top-k
        SoftmaxTopKPass(row, numTiles);
        PostProcess(row);
    }

    __aicore__ inline int32_t CurLenForTile(int32_t ti, int32_t numTiles) {
        return (ti == numTiles - 1 && N_ % tileLen_ != 0) ? tailTileLen_ : tileLen_;
    }

    __aicore__ inline void SoftmaxMaxPass(int32_t row, int32_t numTiles) {
        auto maxLocal = maxBuf_.Get<float>();
        auto reduceLocal = reduceBuf_.Get<float>();
        for (int32_t ti = 0; ti < numTiles; ++ti) {
            int32_t col = ti * tileLen_;
            int32_t curLen = CurLenForTile(ti, numTiles);
            auto inLocal = queIn_.AllocTensor<T>();
            AscendC::DataCopyExtParams cp{1, U32_MUL(curLen, sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
            AscendC::DataCopyPad(inLocal, xGm_[row * N_ + col], cp, pp);
            queIn_.EnQue(inLocal);
            auto xIn = queIn_.DeQue<T>();
            AscendC::LocalTensor<float> xF32;
            if constexpr (std::is_same_v<T, float>) {
                xF32 = xIn.template ReinterpretCast<float>();
            } else {
                xF32 = castFp32Buf_.Get<float>();
                AscendC::Cast(xF32, xIn, AscendC::RoundMode::CAST_NONE, curLen);
                AscendC::PipeBarrier<PIPE_V>();
            }
            AscendC::ReduceMax<float>(xF32, xF32, reduceLocal, curLen);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Max(maxLocal, maxLocal, xF32, 1);
            AscendC::PipeBarrier<PIPE_V>();
            queIn_.FreeTensor(xIn);
        }
    }

    __aicore__ inline void SoftmaxExpSumPass(int32_t row, int32_t numTiles) {
        auto maxLocal = maxBuf_.Get<float>();
        auto sumLocal = sumBuf_.Get<float>();
        auto reduceLocal = reduceBuf_.Get<float>();
        float maxVal = maxLocal.GetValue(0);
        for (int32_t ti = 0; ti < numTiles; ++ti) {
            int32_t col = ti * tileLen_;
            int32_t curLen = CurLenForTile(ti, numTiles);
            auto inLocal = queIn_.AllocTensor<T>();
            AscendC::DataCopyExtParams cp{1, U32_MUL(curLen, sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
            AscendC::DataCopyPad(inLocal, xGm_[row * N_ + col], cp, pp);
            queIn_.EnQue(inLocal);
            auto xIn = queIn_.DeQue<T>();
            AscendC::LocalTensor<float> xF32;
            if constexpr (std::is_same_v<T, float>) {
                xF32 = xIn.template ReinterpretCast<float>();
            } else {
                xF32 = castFp32Buf_.Get<float>();
                AscendC::Cast(xF32, xIn, AscendC::RoundMode::CAST_NONE, curLen);
                AscendC::PipeBarrier<PIPE_V>();
            }
            // x = x - max (numerical stability)
            AscendC::Adds(xF32, xF32, static_cast<float>(-maxVal), curLen);
            AscendC::PipeBarrier<PIPE_V>();
            // exp(x - max)
            auto expLocal = expBuf_.Get<float>();
            AscendC::Exp(expLocal, xF32, curLen);
            AscendC::PipeBarrier<PIPE_V>();
            // Accumulate sum via ReduceSum
            AscendC::ReduceSum<float>(expLocal, expLocal, reduceLocal, curLen);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(sumLocal, sumLocal, expLocal, 1);
            AscendC::PipeBarrier<PIPE_V>();
            // Store exp to workspace GM (for later softmax/topk pass)
            AscendC::Exp(expLocal, xF32, curLen);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopyExtParams cp2{1, U32_MUL(curLen, sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPad(workspaceGm_[row * N_ + col], expLocal, cp2);
            queIn_.FreeTensor(xIn);
