    __aicore__ inline void SoftmaxTopKPass(int32_t row, int32_t numTiles) {
        auto sumLocal = sumBuf_.Get<float>();
        float sumVal = sumLocal.GetValue(0);
        float invSum = (sumVal > 0.0f) ? (1.0f / sumVal) : 1.0f;
        {
            auto tv = topkValBuf_.Get<float>();
            auto ti = topkIdxBuf_.Get<int32_t>();
            AscendC::Duplicate<float>(tv, -3.402823466e+38f, MAX_K);
            AscendC::Duplicate<int32_t>(ti, 0, MAX_K);
        }
        for (int32_t ti = 0; ti < numTiles; ++ti) {
            int32_t col = ti * tileLen_;
            int32_t curLen = CurLenForTile(ti, numTiles);
            auto expF32 = expBuf_.Get<float>();
            AscendC::DataCopyExtParams cp{1, U32_MUL(curLen, sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPadExtParams<float> pp{false, 0, 0, 0.0f};
            AscendC::DataCopyPad(expF32, workspaceGm_[row * N_ + col], cp, pp);
            AscendC::PipeBarrier<PIPE_MTE2>();
            StreamingTopKInline(curLen, col, expF32, invSum);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    __aicore__ inline void StreamingTopKInline(int32_t curLen, int32_t colBase,
                                                AscendC::LocalTensor<float> &vals, float inv) {
        auto topV = topkValBuf_.Get<float>();
        auto topI = topkIdxBuf_.Get<int32_t>();
        for (int32_t i = 0; i < curLen; ++i) {
            float raw = vals.GetValue(i);
            if (raw <= -3.0e38f) continue;
            float v = raw * inv;
            int32_t idx = colBase + i;
            // Insertion sort into running top-k buffer (maintained in descending order)
            int32_t pos = -1;
            for (int32_t p = 0; p < K_; ++p) {
                if (v > topV.GetValue(p)) { pos = p; break; }
            }
            if (pos >= 0 && pos < K_) {
                for (int32_t p = K_ - 1; p > pos; --p) {
                    topV.SetValue(p, topV.GetValue(p - 1));
                    topI.SetValue(p, topI.GetValue(p - 1));
                }
                topV.SetValue(pos, v);
                topI.SetValue(pos, idx);
            }
        }
    }

    __aicore__ inline void PostProcess(int32_t row) {
        auto topV = topkValBuf_.Get<float>();
        auto topI = topkIdxBuf_.Get<int32_t>();

        // Finish mask: replace indices with num_expert for finished rows
        if (hasFinished_ == 1 && finishedGm_.GetValue(row) != 0) {
            AscendC::Duplicate<int32_t>(topI, N_, K_);
        }

        // Write top-k values (with optional cast back to input dtype)
        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopyExtParams cp{1, U32_MUL(K_, sizeof(float)), 0, 0, 0};
            AscendC::DataCopyPad(outGm_[row * K_], topV, cp);
        } else {
            auto outVal = queOut_.AllocTensor<T>();
            AscendC::RoundMode rm = std::is_same_v<T, bfloat16_t> ?
                AscendC::RoundMode::CAST_ROUND : AscendC::RoundMode::CAST_NONE;
            AscendC::Cast(outVal, topV, rm, K_);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopyExtParams cp2{1, U32_MUL(K_, sizeof(T)), 0, 0, 0};
            AscendC::DataCopyPad(outGm_[row * K_], outVal, cp2);
            queOut_.FreeTensor(outVal);
        }

        // Write top-k indices (int32)
        AscendC::DataCopyExtParams cp{1, U32_MUL(K_, sizeof(int32_t)), 0, 0, 0};
        AscendC::DataCopyPad(indicesGm_[row * K_], topI, cp);

        // Generate source_row_out: arange(batch*k).reshape(k,batch).T
        // => source_row_out[row, j] = j * M + row
        auto srcRow = srcRowBuf_.Get<int32_t>();
        for (int32_t j = 0; j < K_; ++j) {
            srcRow.SetValue(j, j * M_ + row);
        }
        AscendC::PipeBarrier<PIPE_V>();
        AscendC::DataCopyExtParams cp2{1, U32_MUL(K_, sizeof(int32_t)), 0, 0, 0};
        AscendC::DataCopyPad(srcRowOutGm_[row * K_], srcRow, cp2);
    }

    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> queIn_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> queOut_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castFp32Buf_, expBuf_, topkValBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> topkIdxBuf_, maxBuf_, sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_, srcRowBuf_;
    AscendC::GlobalTensor<T> xGm_;
    AscendC::GlobalTensor<int32_t> finishedGm_;
    AscendC::GlobalTensor<float> workspaceGm_;
    AscendC::GlobalTensor<T> outGm_;
    AscendC::GlobalTensor<int32_t> indicesGm_;
    AscendC::GlobalTensor<int32_t> srcRowOutGm_;
    int32_t M_, N_, K_, hasFinished_, tileLen_, tailTileLen_;
    int32_t usedCoreNum_, rowsPerCore_, rowStart_, rowEnd_;
};

