// MoeGatingTopKSoftmax op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Flattens leading dims to batch_size, launches kernel for softmax+topK per row
// Supports float32 (dtypeFlag=0), float16 (dtypeFlag=1), bfloat16 (dtypeFlag=2)

#include <algorithm>
#include <cstdint>
#include <vector>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_moe_gating_topk_softmax.h"

namespace ascend_kernel {

constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
constexpr int32_t DEFAULT_TILE_LEN = 2048;

std::vector<at::Tensor> moe_gating_topk_softmax(
    const at::Tensor &x,
    const c10::optional<at::Tensor> &finishedOptional,
    int64_t k)
{
    // Input validation
    TORCH_CHECK(x.dim() >= 2, "x must have at least 2 dimensions, got ", x.dim());
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(k > 0, "k must be positive");

    // Flatten all leading dimensions to get [batch_size, num_experts]
    int32_t numExperts = static_cast<int32_t>(x.sizes().back());
    int32_t batchSize = 1;
    for (int64_t i = 0; i < x.dim() - 1; ++i) {
        batchSize *= static_cast<int32_t>(x.sizes()[i]);
    }
    at::Tensor xFlat = x.reshape({batchSize, numExperts}).contiguous();

    int32_t M = batchSize;
    int32_t N = numExperts;
    int32_t K_val = static_cast<int32_t>(k);

    // finished_optional: convert bool to int32 for kernel
    int32_t hasFinished = 0;
    at::Tensor finishedTensor;
    if (finishedOptional.has_value()) {
        hasFinished = 1;
        finishedTensor = finishedOptional.value();
        TORCH_CHECK(finishedTensor.dim() == 1, "finished_optional must be 1D");
        TORCH_CHECK(static_cast<int32_t>(finishedTensor.sizes()[0]) == M,
                    "finished_optional batch size mismatch, expected ", M,
                    " got ", finishedTensor.sizes()[0]);
        TORCH_CHECK(finishedTensor.scalar_type() == at::kBool,
                    "finished_optional must be bool");
        finishedTensor = finishedTensor.to(at::kInt);
    } else {
        finishedTensor = at::zeros({M}, at::TensorOptions().dtype(at::kInt).device(x.device()));
    }

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Output allocation
    auto optionsVal = x.options();
    auto optionsIdx = at::TensorOptions().dtype(at::kInt).device(x.device());
    at::Tensor out = at::empty({M, K_val}, optionsVal);
    at::Tensor indices = at::empty({M, K_val}, optionsIdx);
    at::Tensor sourceRowOut = at::empty({M, K_val}, optionsIdx);

    // Internal workspace (float32, stored in GM) for softmax intermediate
    at::Tensor workspace = at::empty({M, N}, optionsVal.dtype(at::kFloat));

    // Tiling calculation
    int32_t usedCoreNum = std::min(DEFAULT_NUM_PHYSICAL_CORES, std::max(1, M));
    int32_t rowsPerCore = (M + usedCoreNum - 1) / usedCoreNum;

    int32_t tileLen = std::min(DEFAULT_TILE_LEN, N);
    if (tileLen % 32 != 0) {
        tileLen = ((tileLen / 32) + 1) * 32;
    }
    int32_t tailTileLen = N % tileLen;
    if (tailTileLen == 0) {
        tailTileLen = tileLen;
    }

    // EXEC_KERNEL_CMD requires all params as left values
    int32_t mVal = M;
    int32_t nVal = N;
    int32_t kVal = K_val;
    int32_t hasFinishedVal = hasFinished;
    int32_t tileLenVal = tileLen;
    int32_t tailTileLenVal = tailTileLen;
    int32_t usedCoreNumVal = usedCoreNum;
    int32_t rowsPerCoreVal = rowsPerCore;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(moe_gating_topk_softmax, blockDim,
                    xFlat, finishedTensor, workspace, out, indices, sourceRowOut,
                    mVal, nVal, kVal, hasFinishedVal,
                    tileLenVal, tailTileLenVal, usedCoreNumVal, rowsPerCoreVal,
                    dtypeFlag);

    return {out, indices, sourceRowOut};
}

}  // namespace ascend_kernel
